func batcher(in <-chan Item, flush func([]Item)) {
    buf := make([]Item, 0, 256)
    t := time.NewTicker(5 * time.Millisecond)
    for {
        select {
        case it := <-in:
            buf = append(buf, it)
            if len(buf) >= 256 { flush(buf); buf = buf[:0] }
        case <-t.C:
            if len(buf) > 0 { flush(buf); buf = buf[:0] }
        }
    }
}

